From a2c581191e84a47ead1d4a87b39407a6e4b3c36a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:07:19 +0100
Subject: [PATCH] plasmacomponents3: make Label follow system font changes

Labels in Plasma kept the font they were created with, because Plasma
windows don't propagate font changes to existing items and the Plasma
theme never refreshed its fonts. Refresh them and bind Label to them.

BUG: 480004
---
 .../kirigamiplasmastyle/plasmatheme.cpp       | 35 +++++++++++++++++++
 .../kirigamiplasmastyle/plasmatheme.h         |  1 +
 .../plasmacomponents3/Label.qml               |  2 +-
 3 files changed, 37 insertions(+), 1 deletion(-)

diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
index eb317484e..045bb0927 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
@@ -7,6 +7,7 @@
 #include "plasmatheme.h"
 #include <KIconLoader>
 #include <QDebug>
+#include <QFontDatabase>
 #include <QGuiApplication>
 #include <QPalette>
 #include <QQmlContext>
@@ -19,6 +20,30 @@
 #include <KConfigGroup>
 #include <KIconColors>

+class FontWatcher : public QObject
+{
+public:
+    FontWatcher()
+    {
+        qGuiApp->installEventFilter(this);
+    }
+
+    QList<PlasmaTheme *> watchers;
+
+protected:
+    bool eventFilter(QObject *obj, QEvent *event) override
+    {
+        if (obj == qGuiApp && event->type() == QEvent::ApplicationFontChange) {
+            for (auto watcher : std::as_const(watchers)) {
+                watcher->syncFonts();
+            }
+        }
+        return false;
+    }
+};
+
+Q_GLOBAL_STATIC(FontWatcher, s_fontWatcher)
+
 PlasmaTheme::PlasmaTheme(QObject *parent)
     : PlatformTheme(parent)
 {
@@ -37,6 +62,7 @@ PlasmaTheme::PlasmaTheme(QObject *parent)
     }

     setDefaultFont(qGuiApp->font());
+    s_fontWatcher->watchers.append(this);

     KSharedConfigPtr ptr = KSharedConfig::openConfig();
     KConfigGroup general(ptr->group(QStringLiteral("general")));
@@ -60,6 +86,9 @@ PlasmaTheme::PlasmaTheme(QObject *parent)

 PlasmaTheme::~PlasmaTheme()
 {
+    if (s_fontWatcher.exists()) {
+        s_fontWatcher->watchers.removeOne(this);
+    }
 }

 QIcon PlasmaTheme::iconFromTheme(const QString &name, const QColor &customColor)
@@ -164,6 +193,12 @@ void PlasmaTheme::syncColors()
     setFrameContrast(KColorScheme::frameContrast());
 }

+void PlasmaTheme::syncFonts()
+{
+    setDefaultFont(qGuiApp->font());
+    setSmallFont(QFontDatabase::systemFont(QFontDatabase::SmallestReadableFont));
+}
+
 void PlasmaTheme::syncFrameContrast()
 {
     if (QCoreApplication::closingDown()) {
diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
index 462c8713d..0cfa8c985 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
@@ -30,6 +30,7 @@ public:

     void syncWindow();
     void syncColors();
+    void syncFonts();
     void syncFrameContrast();

 protected:
